ee:message.ee:set-payload:
%dw 2.0
output application/json

var campaign = payload
var requestedCampaignId = vars.campaignId
var currentTime = now()

var activeFrom =
    campaign.activeFrom as LocalDateTime {
        format: "yyyy-MM-dd'T'HH:mm:ss"
    }

var activeTo =
    campaign.activeTo as LocalDateTime {
        format: "yyyy-MM-dd'T'HH:mm:ss"
    }

var currentLocalTime =
    currentTime as LocalDateTime

---
{
    campaignId: requestedCampaignId,
    campaignName: campaign.campaignName,
    campaignStatus: campaign.campaignStatus,

    validationStatus:
        if (campaign.campaignId != requestedCampaignId)
            "NOT_FOUND"
        else if (campaign.campaignStatus != "APPROVED")
            "NOT_APPROVED"
        else if (currentLocalTime < activeFrom)
            "NOT_YET_ACTIVE"
        else if (currentLocalTime > activeTo)
            "EXPIRED"
        else
            "VALID",

    approvedBy: campaign.approvedBy,
    ownerEmail: campaign.ownerEmail
}

%dw 2.0
output application/json
---
{
    campaign: payload.campaign,
    customers: payload.customers map ((customer) ->
        customer ++ {
            allowedChannels:
                (if (customer.emailConsent ) ["EMAIL"] else [])
                ++
                (if (customer.smsConsent ) ["SMS"] else [])
                ++
                (if (customer.pushConsent ) ["PUSH"] else [])
        }
    )
}

%dw 2.0
output application/json

// Temporary hardcoded suppression list
var suppressionList = ["CUST002"]

---
{
    campaign: payload.campaign,
    customers: payload.customers map ((customer) ->
        customer ++ {
            suppressionStatus:
                if (suppressionList contains customer.customerId)
                    "SUPPRESSED"
                else
                    "NOT_SUPPRESSED"
        }
    )
}

%dw 2.0
output application/json

var contactHistory = [
    {customerId: "CUST001", contactedAt: now() - |P1D|},
    {customerId: "CUST001", contactedAt: now() - |P3D|},
    {customerId: "CUST001", contactedAt: now() - |P5D|},
    {customerId: "CUST003", contactedAt: now() - |P1D|},
    {customerId: "CUST004", contactedAt: now() - |P4D|}
]

var customers =
    (payload.customers default []) as Array<Object>

var campaign = payload.campaign

var currentTime = now()
var weekStart = currentTime - |P7D|

---
{
    campaign: campaign,

    customers: customers map ((customer) -> do {

        var history =
            contactHistory filter ((record) ->
                record.customerId == customer.customerId
                and record.contactedAt >= weekStart
                and record.contactedAt <= currentTime
            )

        var historyCount = sizeOf(history)

        var lastContact =
            if (historyCount > 0)
                (history maxBy $.contactedAt).contactedAt
            else
                null

        var shouldCheck =
            customer.suppressionStatus == "NOT_SUPPRESSED"
            and !isEmpty(customer.allowedChannels default [])

        var minimumGapNotMet =
            if (lastContact == null)
                false
            else
                currentTime < ((lastContact as DateTime) + |PT48H|)

        var frequencyReason =
            if (historyCount >= 3)
                "WEEKLY_CAP_EXCEEDED"
            else if (minimumGapNotMet)
                "MINIMUM_48_HOURS_NOT_MET"
            else
                null

        ---
        customer ++ {
            messagesInLast7Days: historyCount,

            frequencyStatus:
                if (!shouldCheck)
                    "NOT_CHECKED"
                else if (frequencyReason != null)
                    "EXCLUDED"
                else
                    "ELIGIBLE",

            frequencyExclusionReason:
                if (shouldCheck)
                    frequencyReason
                else
                    null
        }
    })
}

%dw 2.0
output application/json
---
{
    campaign: payload.campaign,
    customers: payload.customers map ((customer) -> do {

        var allowed =
            (customer.allowedChannels default [])
                map ((channel) -> channel as String)

        var reachable =
            if (customer.frequencyStatus != "ELIGIBLE")
                []
            else
                allowed filter ((channel) ->
                    if (channel == "EMAIL")
                        !isEmpty(customer.email default "")
                    else if (channel == "SMS")
                        !isEmpty(customer.mobile default "")
                    else if (channel == "PUSH")
                        !isEmpty(customer.pushToken default "")
                    else
                        false
                )

        var unreachable =
            allowed filter ((channel) ->
                !(reachable contains channel)
            )

        ---
        customer ++ {
            reachableChannels: reachable,
            unreachableChannels: unreachable,
            reachabilityStatus:
                if (customer.frequencyStatus != "ELIGIBLE")
                    "NOT_CHECKED"
                else if (isEmpty(reachable))
                    "UNREACHABLE"
                else
                    "REACHABLE"
        }
    })
}

%dw 2.0
output application/json

var requestedChannels = vars.requestData.channels default []

var preferenceRecords = [
    {customerId: "CUST001", preferredChannels: ["EMAIL", "PUSH"]},
    {customerId: "CUST002", preferredChannels: ["SMS"]},
    {customerId: "CUST003", preferredChannels: ["PUSH"]},
    {customerId: "CUST004", preferredChannels: ["SMS", "EMAIL"]},
    {customerId: "CUST005", preferredChannels: ["EMAIL"]}
]

---
{
    campaign: payload.campaign,
    customers: payload.customers map ((customer) -> do {

        var preference =
            (preferenceRecords filter ((record) ->
                record.customerId == customer.customerId
            ))[0].preferredChannels default []

        var availableChannels =
            (customer.reachableChannels default [])
                filter ((channel) ->
                    requestedChannels contains channel
                )

        var preferred =
            availableChannels filter ((channel) ->
                preference contains channel
            )

        var other =
            availableChannels filter ((channel) ->
                !(preference contains channel)
            )

        ---
        customer ++ {
            preferredChannels: preferred,
            selectedChannels: preferred ++ other
        }
    })
}

%dw 2.0
output application/json

var customerSchedule = [
    {
        customerId: "CUST001",
        timezone: "Asia/Kolkata",
        quietHoursStart: "21:00",
        quietHoursEnd: "09:00"
    },
    {
        customerId: "CUST002",
        timezone: "Asia/Kolkata",
        quietHoursStart: "21:00",
        quietHoursEnd: "09:00"
    },
    {
        customerId: "CUST003",
        timezone: "Asia/Kolkata",
        quietHoursStart: "21:00",
        quietHoursEnd: "09:00"
    },
    {
        customerId: "CUST004",
        timezone: "Asia/Kolkata",
        quietHoursStart: "21:00",
        quietHoursEnd: "09:00"
    },
    {
        customerId: "CUST005",
        timezone: "Asia/Kolkata",
        quietHoursStart: "21:00",
        quietHoursEnd: "09:00"
    }
]

---
{
    campaign: payload.campaign,
    customers: payload.customers map ((customer) -> do {
        var schedule =
            (customerSchedule filter ((item) ->
                item.customerId == customer.customerId
            ))[0]
        ---
        customer ++ {
            timezone: schedule.timezone,
            quietHoursStart: schedule.quietHoursStart,
            quietHoursEnd: schedule.quietHoursEnd
        }
    })
}

%dw 2.0
output application/json

var currentTime = now()

---
{
    campaign: payload.campaign,
    customers: payload.customers map ((customer) -> do {

        var localTime =
            currentTime >> customer.timezone

        var localHour =
            localTime.hour

        var localMinute =
            localTime.minute

        var currentMinutes =
            localHour * 60 + localMinute

        var quietStart = 21 * 60
        var quietEnd = 9 * 60

        var isQuietHours =
            currentMinutes >= quietStart
            or currentMinutes < quietEnd

        ---
        customer ++ {
            schedulingStatus:
                if (isEmpty(customer.selectedChannels default []))
                    "NOT_SCHEDULED"
                else if (customer.frequencyStatus != "ELIGIBLE")
                    "NOT_SCHEDULED"
                else if (isQuietHours)
                    "DEFERRED"
                else
                    "READY",
            scheduledSendAt:
                if (isQuietHours)
                    (
                        (localTime as Date) + |P1D|
                    ) ++ |PT9H|
                else
                    localTime
        }
    })
}

%dw 2.0 output application/json
var recipientRecords = flatten( (payload.customers default []) map ((customer) -> (customer.selectedChannels default []) map ((channel) -> { customerId: (customer.customerId default "") as String, channel: (channel default "") as String,
email: customer.email, mobile: customer.mobile, pushToken: customer.pushToken,
firstName: customer.firstName, lastName: customer.lastName, customerTier: customer.customerTier, rewardPoints: customer.rewardPoints, offerCode: customer.offerCode, offerExpiry: customer.offerExpiry, recommendedCategory: customer.recommendedCategory, unsubscribeUrl: customer.unsubscribeUrl, senderIdentity: customer.senderIdentity,
timezone: customer.timezone, schedulingStatus: customer.schedulingStatus, scheduledSendAt: customer.scheduledSendAt, frequencyStatus: customer.frequencyStatus, reachabilityStatus: customer.reachabilityStatus }) ) )
var validRecords = recipientRecords filter ((record) -> !isEmpty(record.customerId) and !isEmpty(record.channel) )
var uniqueRecords = validRecords distinctBy ((record) -> { customerId: record.customerId, channel: record.channel })
--- { campaign: payload.campaign, customers: payload.customers, recipientChannels: uniqueRecords }

%dw 2.0 output application/json
// Explicitly treat recipientChannels as an array of objects var sourceRecords = (payload.recipientChannels default []) as Array<Object>
var records = sourceRecords map ((record) -> { customerId: (record.customerId default "") as String, channel: (record.channel default "") as String,
address: if ((record.channel default "") as String == "EMAIL") (record.email default "") as String else if ((record.channel default "") as String == "SMS") (record.mobile default "") as String else if ((record.channel default "") as String == "PUSH") (record.pushToken default "") as String else "",
email: record.email default null, mobile: record.mobile default null, pushToken: record.pushToken default null,
firstName: record.firstName, lastName: record.lastName, customerTier: record.customerTier, rewardPoints: record.rewardPoints, offerCode: record.offerCode, offerExpiry: record.offerExpiry, recommendedCategory: record.recommendedCategory, unsubscribeUrl: record.unsubscribeUrl, senderIdentity: record.senderIdentity,
timezone: record.timezone, schedulingStatus: record.schedulingStatus, scheduledSendAt: record.scheduledSendAt })
var validRecords = (records filter ((record) -> !isEmpty(record.address) )) as Array<Object>
var uniqueRecords = validRecords distinctBy ((record) -> { channel: record.channel, address: record.address })
--- { campaign: payload.campaign, customers: payload.customers, recipientChannels: uniqueRecords, duplicateAddressCount: sizeOf(validRecords) - sizeOf(uniqueRecords), invalidAddressCount: sizeOf(records) - sizeOf(validRecords) }

%dw 2.0
output application/json

var campaign = payload.campaign

var recipients =
    (payload.recipientChannels default []) as Array<Object>

var renderedMessages =
    recipients map ((recipient) -> do {

        var customerName =
            (recipient.firstName default "") as String

        var offerCode =
            (recipient.offerCode default "") as String

        var offerExpiry =
            (recipient.offerExpiry default "") as String

        var category =
            (recipient.recommendedCategory default "") as String

        var tier =
            (recipient.customerTier default "") as String

        var points =
            (recipient.rewardPoints default 0) as String

        ---
        recipient ++ {
            templateId:
                if (recipient.channel == "EMAIL")
                    "TMPL-FESTIVE-EMAIL-V4"
                else if (recipient.channel == "SMS")
                    "TMPL-FESTIVE-SMS-V2"
                else
                    "TMPL-FESTIVE-PUSH-V1",

            message:
                if (recipient.channel == "EMAIL")
                    {
                        subject: "A special offer for you, " ++ customerName,
                        body:
                            "Hello " ++ customerName ++ ",\n\n" ++
                            "Enjoy your exclusive festive offer!\n" ++
                            "Customer Tier: " ++ tier ++ "\n" ++
                            "Reward Points: " ++ points ++ "\n" ++
                            "Offer Code: " ++ offerCode ++ "\n" ++
                            "Offer Expiry: " ++ offerExpiry ++ "\n" ++
                            "Recommended Category: " ++ category ++ "\n\n" ++
                            "Unsubscribe: " ++
                            (recipient.unsubscribeUrl default "")
                    }
                else if (recipient.channel == "SMS")
                    {
                        registeredTemplateRef: "DLT-FEST-2026-001",
                        senderId: "COMPNY",
                        body:
                            "Hi " ++ customerName ++
                            "! Use " ++ offerCode ++
                            " for festive offers on " ++ category ++
                            ". Valid till " ++ offerExpiry ++
                            ". Reply STOP to opt out."
                    }
                else
                    {
                        title: "A festive offer is waiting!",
                        body:
                            "Hi " ++ customerName ++
                            "! Use " ++ offerCode ++
                            " to enjoy offers on " ++ category ++
                            ". Valid till " ++ offerExpiry ++ "."
                    }
        }
    })

---
{
    campaign: campaign,
    customers: payload.customers,
    recipientChannels: renderedMessages,
    recipientCount: sizeOf(renderedMessages)
}
